#!/usr/bin/env python3
"""
jev-risk-shadow.py

Opt-in, shadow-only Jev second opinion for the proofread pipeline's
`meaningRisk` labels. Reads a changes-schema.json payload
(src/skills/proofread/references/changes-schema.json), asks TypeSafe AI's Jev
model how much each eligible edit changes meaning, and appends one JSONL row per
change to a project-local ledger.

This script never modifies the changes file, never blocks the proofreading
pipeline, and is disabled by default. It writes only when
proofread.jevShadow.enabled is true in thresholds.json or AW_JEV_SHADOW=1 is set.

Usage:
    python3 jev-risk-shadow.py --changes changes.json --filebase article-slug

--changes     Path to a JSON file matching changes-schema.json.
--filebase    Article/file base name to copy into each shadow ledger row.
--ledger      JSONL ledger path. Defaults to .academic-helper/jev-shadow.jsonl
              relative to the current working directory, never $HOME.
--thresholds  thresholds.json path. Defaults to ../thresholds.json relative to
              this script, falling back to src/thresholds.json when run from the
              repository checkout.

No third-party dependencies -- Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import datetime as _dt
import json
import os
import subprocess
import sys
import urllib.error
import urllib.request
from pathlib import Path
from typing import Callable, Optional

API_URL = "https://api.typesafe.ai/v1/systemone"
DEFAULT_MODEL = "jev-1.13.0"
DEFAULT_FLAG_SCORE = 1.5
QUESTION_INSTRUCTIONS = (
    "The Hebrew text `before` was edited into `after`. How much does the edit "
    "change what the text says?"
)
QUESTION_CRITERIA = [
    "Only spelling, punctuation or typography changed; the wording and the claim are identical",
    "Wording or syntax changed; the claim is the same but emphasis or nuance may shift",
    "The claim, argument, or information content changed",
]


def candidates(payload: dict) -> list[dict]:
    """Return changes with a non-empty `before` and string `after`."""
    changes = payload.get("changes", [])
    if not isinstance(changes, list):
        return []

    result: list[dict] = []
    for change in changes:
        if not isinstance(change, dict):
            continue
        before = change.get("before")
        after = change.get("after")
        if before and isinstance(after, str):
            result.append(change)
    return result


def shadow_row(change: dict, score: float, flag_score: float, model: str) -> dict:
    """Build one JSON-serializable ledger row for a Jev score."""
    meaning_risk = change.get("meaningRisk")
    flags_risk = score >= flag_score
    return {
        "ts": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "stage": change.get("stage"),
        "line": change.get("line"),
        "type": change.get("type"),
        "meaningRisk": meaning_risk,
        "before": change.get("before"),
        "after": change.get("after"),
        "jevScore": score,
        "jevModel": model,
        "jevFlagsRisk": flags_risk,
        "disagree": (meaning_risk == "low") == flags_risk,
    }


def run(
    changes_path,
    ledger_path,
    filebase,
    flag_score,
    model,
    ask: Callable[[dict], float],
) -> int:
    """Append one shadow ledger row per candidate whose Jev request succeeds."""
    payload = json.loads(Path(changes_path).read_text(encoding="utf-8"))
    rows = []
    for change in candidates(payload):
        try:
            score = float(ask(change))
        except Exception:
            continue
        row = shadow_row(change, score, flag_score, model)
        row["filebase"] = filebase
        rows.append(row)

    if not rows:
        return 0

    ledger = Path(ledger_path)
    ledger.parent.mkdir(parents=True, exist_ok=True)
    with ledger.open("a", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")
    return len(rows)


def default_thresholds_path() -> Path:
    script_path = Path(__file__).resolve()
    nearby = script_path.parent.parent / "thresholds.json"
    if nearby.exists():
        return nearby
    repo_src = Path.cwd() / "src" / "thresholds.json"
    if repo_src.exists():
        return repo_src
    return nearby


def load_shadow_config(thresholds_path: Path) -> dict:
    with thresholds_path.open(encoding="utf-8") as handle:
        data = json.load(handle)
    block = data.get("proofread", {}).get("jevShadow", {})
    if not isinstance(block, dict):
        return {}
    return block


def keychain_api_key() -> Optional[str]:
    try:
        result = subprocess.run(
            ["security", "find-generic-password", "-s", "typesafe-api-key", "-w"],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if result.returncode != 0:
        return None
    key = result.stdout.strip()
    return key or None


def api_key() -> Optional[str]:
    return os.environ.get("TYPESAFE_API_KEY") or keychain_api_key()


def make_ask(key: str, model: str) -> Callable[[dict], float]:
    def ask(change: dict) -> float:
        body = {
            "model": model,
            "state": {
                "before": change.get("before"),
                "after": change.get("after"),
            },
            "questions": {
                "risk": {
                    "type": "score",
                    "instructions": QUESTION_INSTRUCTIONS,
                    "criteria": QUESTION_CRITERIA,
                }
            },
        }
        request = urllib.request.Request(
            API_URL,
            data=json.dumps(body, ensure_ascii=False).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {key}",
                "Content-Type": "application/json",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                payload = json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            print(f"http error {exc.code}")
            raise
        return float(payload["answers"]["risk"]["score"])

    return ask


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Opt-in Jev shadow scorer for proofread meaningRisk labels."
    )
    parser.add_argument("--changes", required=True, help="Path to changes JSON.")
    parser.add_argument("--filebase", required=True, help="Filebase copied into ledger rows.")
    parser.add_argument(
        "--ledger",
        default=".academic-helper/jev-shadow.jsonl",
        help="Project-local JSONL ledger path.",
    )
    parser.add_argument(
        "--thresholds",
        default=str(default_thresholds_path()),
        help="Path to thresholds.json.",
    )
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        config = load_shadow_config(Path(args.thresholds))
    except (OSError, json.JSONDecodeError) as exc:
        print(f"thresholds unavailable: {exc}")
        return 0

    enabled = bool(config.get("enabled")) or os.environ.get("AW_JEV_SHADOW") == "1"
    if not enabled:
        print("jev-risk-shadow disabled")
        return 0

    # Only setup/init may create .academic-helper/ (CLAUDE.md anti-patterns), so a
    # missing ledger directory means "not an academic-writer project": skip.
    if not Path(args.ledger).parent.is_dir():
        print(f"jev-risk-shadow skipped: {Path(args.ledger).parent} does not exist")
        return 0

    key = api_key()
    if not key:
        print("jev-risk-shadow no key")
        return 0

    flag_score = float(config.get("flagScore", DEFAULT_FLAG_SCORE))
    model = str(config.get("model", DEFAULT_MODEL))
    real_ask = make_ask(key, model)
    scored: list[tuple[dict, float]] = []

    def ask_and_track(change: dict) -> float:
        score = float(real_ask(change))
        scored.append((change, score))
        return score

    try:
        rows = run(args.changes, args.ledger, args.filebase, flag_score, model, ask_and_track)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        print(f"jev-risk-shadow skipped: {exc}")
        return 0

    disagreements = sum(
        int(bool(shadow_row(change, score, flag_score, model)["disagree"]))
        for change, score in scored
    )

    print(f"jev-risk-shadow rows={rows} disagreements={disagreements}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
